function openApartmentRecords(id){if(!canLeave())return;recordsTab=true;recordsComplex=id;recordsDong=null;recordsSort='date';recordsScope='complex';writePageUrl(null,false,{fromApartments:true});render();currentPageTop();}

function selectComplex(id){if(!state.complexes.some(c=>c.id===id)||!canLeave())return;clearDraft();selectedComplex=id;selectedBuilding=null;selectedVisit=null;recordPage=false;addingRecord=false;placement=null;writePageUrl(id);render();void prepareDetailMap();showPageTop('#detail-page');}

function selectBuilding(id,{compose=true}={}){const target=complex()?.buildings.find(b=>b.id===id);if(!target||!canLeave())return;clearDraft();selectedBuilding=id;selectedVisit=null;recordPage=true;addingRecord=false;formOpen=compose||!target.visits.length;placement=null;writePageUrl(selectedComplex);render();showPageTop('#record-page');}
async function requestBuildingRecord(id){const c=complex(),b=c?.buildings.find(x=>x.id===id);if(!b||!canLeave())return;const proceed=await confirmAction(b.name+'에 기록을 추가할까요?',c.name+' '+b.name+'의 임장 기록 추가 페이지로 이동합니다.','진행');if(proceed&&selectedComplex===c.id)startAddRecord({name:b.name});}
function goDetail({toMap=false}={}){if(!canLeave())return;clearDraft();if(history.state?.recordFromMap||(history.state?.fromRecords&&!toMap)){history.back();return;}selectedBuilding=null;selectedVisit=null;recordPage=false;addingRecord=false;placement=null;writePageUrl(selectedComplex,true);render();void prepareDetailMap();showPageTop('#detail-page');}

