function photoUrl(p){return p.startsWith('blob:')?p:'';}
let justSaved=null;
function stamp(date,{latest=false,large=false}={}){const d=new Date(date+'T00:00:00Z'),el=make('span','stamp'+(latest?' latest':'')+(large?' large':''));el.setAttribute('aria-hidden','true');el.append(make('b','',String(d.getUTCDate()).padStart(2,'0')),make('small','',(d.getUTCMonth()+1)+'월 '+'일월화수목금토'[d.getUTCDay()]));return el;}
function allVisits(){const out=[];for(const c of state.complexes)for(const b of c.buildings)for(const v of b.visits)out.push({c,b,v});return out.sort((x,y)=>y.v.date.localeCompare(x.v.date));}
function renderHome(){const visits=demo?[]:allVisits(),places=new Set(visits.map(x=>x.c.id)).size;$('#home-summary').textContent=visits.length?`단지 ${places}곳에서 기록 ${visits.length}개를 모았어요`:'아직 비어 있어요. 첫 단지부터 시작해 볼까요?';$('#home-recent').hidden=!visits.length;$('#home-empty').hidden=!!visits.length||demo;const list=$('#home-recent-list');list.replaceChildren();visits.slice(0,3).forEach(({c,b,v},i)=>{const row=make('button','entry');row.type='button';const text=make('span','entry-text');text.append(make('strong','entry-title',c.name),make('span','entry-sub',[[b.name,v.details?.unit].filter(Boolean).join(' '),v.details&&(v.details.deal||v.details.price)?priceText(v.details):''].filter(Boolean).join(', ')));row.append(stamp(v.date,{latest:i===0}),text);row.setAttribute('aria-label',`${formatVisitDate(v.date)} ${c.name} ${b.name} 기록 열기`);row.onclick=()=>openVisit(c.id,b.id,v.id);list.append(row);});}
function visitCard(c,b,v,showDong,latest=false){const card=make('button','record-card');card.type='button';const body=make('span','record-card-body'),head=make('span','record-card-head');const place=showDong?[b.name,v.details?.unit].filter(Boolean).join(' '):(isComplexRecord(b)?'단지 전체':v.details?.unit||'호수 미기재');head.append(make('h3','',place));const d=v.details||{};if(d.deal||d.price)head.append(make('span','record-card-price',priceText(d)));body.append(head);const tags=recordTags(d).slice(d.deal||d.price?1:0);if(tags.length){const row=make('span','record-tags');for(const t of tags)row.append(make('span','tag',t));body.append(row);}if(v.memo)body.append(make('span','record-card-memo',v.memo));if(v.photos.length)body.append(make('span','record-photos','사진 '+v.photos.length+'장'));card.append(stamp(v.date,{latest}),body);card.setAttribute('aria-label',`${formatVisitDate(v.date)} ${showDong?b.name+' ':''}${place} 기록 열기`);card.onclick=()=>openVisit(c.id,b.id,v.id);return card;}
function openVisit(cid,bid,vid){const c=state.complexes.find(x=>x.id===cid),b=c?.buildings.find(x=>x.id===bid);if(!b?.visits.some(v=>v.id===vid)||!canLeave())return;clearDraft();selectedComplex=cid;selectedBuilding=bid;selectedVisit=vid;recordPage=true;addingRecord=false;formOpen=false;placement=null;writePageUrl(cid,false,{fromList:true});render();currentPageTop();}
function closeVisit(){if(!canLeave())return;clearDraft();formOpen=false;if(history.state?.fromList){history.back();return;}selectedVisit=null;writePageUrl(selectedComplex,true);render();currentPageTop();}
function visitDetail(b,v,{cid=selectedComplex,inline=false}={}){const item=make('article','visit');item.setAttribute('data-visit-id',v.id);const head=make('div','visit-header'),actions=make('div','visit-actions'),when=make('div','visit-when'),whenText=make('div','visit-when-text');const st=stamp(v.date,{large:true,latest:[...b.visits].sort((x,y)=>y.date.localeCompare(x.date))[0]?.id===v.id});if(justSaved===v.id){st.classList.add('stamp-in');justSaved=null;}whenText.append(make('span','visit-date',formatVisitDate(v.date)),make('span','visit-unit',v.details?.unit||b.name));when.append(st,whenText);head.append(when);const edit=make('button','','수정'),del=make('button','','삭제');edit.onclick=()=>{if(!canLeave())return;if(inline)openVisit(cid,b.id,v.id);clearDraft();editing=v.id;formOpen=true;$('#visit-date').value=v.date;$('#memo').value=[v.memo,v.details?.moldNote&&'결로·곰팡이: '+v.details.moldNote].filter(Boolean).join('\n');fillDetails(v.details);draftPhotos=v.photos.map(id=>({id,url:photoUrl(id)}));$('#save-visit').textContent='수정 내용 저장';render();showPageTop('#record-page');};del.onclick=async()=>{if(await confirmAction('기록을 삭제할까요?',`${v.date} 방문 기록이 삭제됩니다.`)){if(await change(s=>{const cx=s.complexes.find(c=>c.id===cid),bx=cx.buildings.find(x=>x.id===b.id);bx.visits=bx.visits.filter(x=>x.id!==v.id);if(!bx.visits.length)cx.buildings=cx.buildings.filter(x=>x.id!==b.id);})){if(inline){toast('기록을 삭제했어요.');return;}if(editing===v.id)clearDraft();selectedVisit=null;if(!building()){dirty=false;clearDraft();selectedBuilding=null;selectedVisit=null;recordPage=false;formOpen=false;writePageUrl(selectedComplex,true);render();void prepareDetailMap();}else{writePageUrl(selectedComplex,true);render();}toast('기록을 삭제했어요.');}}};del.hidden=!!workspace;actions.append(edit,del);head.append(actions);item.append(head);if(v.photos.length){const photos=make('div','photo-grid');for(const p of v.photos){const a=make('a');a.target='_blank';a.rel='noopener';const img=make('img','visit-photo');window.zipzipPhotos.attach(img,p,a);img.alt=b.name+' 임장 사진';img.loading='lazy';a.append(img);photos.append(a);}item.append(photos);}const rows=detailRows(v.details).filter(([label])=>label!=='호수');if(rows.length){const dl=make('dl','visit-details');for(const [label,value] of rows){const row=make('div',label==='가격'?'price':'');row.append(make('dt','',label),make('dd','',value));dl.append(row);}item.append(dl);}if(v.memo){if(rows.length)item.append(make('span','visit-memo-label','메모'));item.append(make('p','visit-memo',v.memo));}else if(!rows.length&&!v.details?.unit)item.append(make('p','visit-memo','사진으로 남긴 임장 기록'));return item;}
function renderPanel(){$('#visit-form').hidden=false;$('#new-visit').hidden=false;const b=building(),adding=addingRecord&&recordPage&&!b&&!!complex(),whole=complexScope();$('#complex-assessment').hidden=!whole;for(const id of ['#property-location','#property-deal','#property-condition','#property-living'])$(id).hidden=whole;$('#memo').placeholder=whole?'교통, 주변 환경, 주차, 조경, 공용시설 등을 남겨 보세요.':'현장에서 발견한 점을 남겨 보세요.';$('#record-panel').hidden=!adding&&(!b||!recordPage);$('#record-dong-row').hidden=!adding||whole;$('#record-dong').required=adding&&!whole;$('.building-actions').hidden=adding;$('.record-tabs').hidden=adding;$('#visit-list').hidden=adding;if(adding){$('#building-title').replaceChildren(make('h2','',whole?'단지 전체 기록':'새 임장 기록'),make('p','',complex().name));const options=$('#record-dong-options');options.replaceChildren();for(const x of realDongs(complex())){const o=make('option');o.value=x.name;options.append(o);}return;}if(!b||!recordPage)return;const open=formOpen||!b.visits.length;$('#visit-form').hidden=!open;$('#new-visit').hidden=open;$('#visit-list').hidden=open;$('#cancel-edit').hidden=!open||!b.visits.length;$('#cancel-edit').textContent=editing?'수정 취소':'취소';const title=$('#building-title');title.replaceChildren(make('h2','',b.name),make('p','',complex().name));$('#visit-count').textContent=b.visits.length;const list=$('#visit-list');list.replaceChildren();const shown=selectedVisit&&b.visits.find(x=>x.id===selectedVisit);$('.record-tabs').hidden=!!editing||(!!shown&&!open);if(shown&&!open){list.append(visitDetail(b,shown));renderDraftPhotos();return;}if(!b.visits.length)list.append(make('p','no-visits','아직 기록이 없어요.\n이 동의 첫인상을 남겨 보세요.'));[...b.visits].sort((a,b)=>b.date.localeCompare(a.date)).forEach((v,i)=>list.append(visitCard(complex(),b,v,false,i===0)));renderDraftPhotos();}
function renderDraftPhotos(){const root=$('#photo-preview');root.replaceChildren();draftPhotos.forEach((p,i)=>{const item=make('div','photo-item'),img=make('img');if(p.file||p.url.startsWith('blob:'))img.src=p.url;else if(p.id)window.zipzipPhotos.attach(img,p.id);img.alt='첨부 사진 '+(i+1);const del=make('button','','×');del.type='button';del.setAttribute('aria-label','첨부 사진 삭제');del.onclick=()=>{if(p.file)URL.revokeObjectURL(p.url);draftPhotos.splice(i,1);dirty=true;renderDraftPhotos();};item.append(img,del);root.append(item);});}
function markerButton(b){const btn=make('button','marker'+(b.visits.length?' has-record':'')+(b.id===selectedBuilding?' selected':''),b.name);btn.setAttribute('aria-label',`${b.name}, 임장 기록 ${b.visits.length}개`);if(b.visits.length)btn.append(make('small','',String(b.visits.length)));btn.onclick=async e=>{e.stopPropagation();await requestBuildingRecord(b.id);};return btn;}
function renderMarkers(){renderFootprints();for(const m of markers)m.setMap(null);markers=[];$('#schematic').querySelectorAll('.sample-marker').forEach(x=>x.remove());const c=complex();if(!c)return;if(demo){realDongs(c).forEach((b,i)=>{const el=make('div','sample-marker');el.style.left=(b.sampleX||25+i*16)+'%';el.style.top=(b.sampleY||35+i%2*25)+'%';el.append(markerButton(b));$('#schematic').append(el);});return;}if(!map)return;const key=footprintKey(c),cached=footprintCache.get(key),outlined=cached?.items||[],waiting=!cached&&!footprintFailed.has(key);for(const b of realDongs(c)){if(outlined.some(x=>x.id===b.id||x.name.trim()===b.name.trim()))continue;if(waiting)continue;const btn=markerButton(b);markers.push(new naver.maps.Marker({position:new naver.maps.LatLng(b.lat,b.lng),map,icon:{content:btn,anchor:new naver.maps.Point(28,15)}}));}}
async function loadMap(key){if(!key){$('#map-placeholder').hidden=false;return;}if(mapLoading)return;mapLoading=true;$('#map-loading').hidden=false;$('#connect-card').hidden=true;try{if(!window.naver?.maps){await new Promise((resolve,reject)=>{window.navermap_authFailure=()=>reject(new Error('네이버 지도 인증에 실패했어요. Maps Key ID와 등록 URL을 확인해 주세요.'));const script=document.createElement('script');const timer=setTimeout(()=>reject(new Error('지도를 불러오지 못했어요. 연결 상태와 API 설정을 확인해 주세요.')),15000);script.src='https://oapi.map.naver.com/openapi/v3/maps.js?ncpKeyId='+encodeURIComponent(key);script.onload=()=>{clearTimeout(timer);window.naver?.maps?resolve():reject(new Error('네이버 지도 연결 설정을 확인해 주세요.'));};script.onerror=()=>{clearTimeout(timer);script.remove();reject(new Error('네이버 지도 스크립트를 불러오지 못했어요.'));};document.head.append(script);});}
 if(!map){map=new naver.maps.Map($('#map'),{size:detailMapSize(),center:new naver.maps.LatLng(complex()?.lat||37.515,complex()?.lng||127.05),zoom:16,zoomControl:false,mapDataControl:true});naver.maps.Event.addListener(map,'click',e=>pointClicked(e.coord.lat(),e.coord.lng()));}$('#map-placeholder').hidden=true;render();}catch(e){toast(e.message);$('#map-placeholder').hidden=false;$('#connect-card').hidden=false;}finally{mapLoading=false;$('#map-loading').hidden=true;}}
