async function openShare(cid){if(demo||workspace){toast('아파트 소유자만 멤버를 관리할 수 있어요.');return;}const c=state.complexes.find(x=>x.id===cid);if(!c)return;shareComplexId=cid;const version=++shareVersion;$('#share-description').textContent=c.name;$('#share-email').value='';$('#share-members').replaceChildren();$('#share-status').textContent='멤버를 확인하는 중…';$('#share-dialog').showModal();shareWorking=true;$('#share-invite').disabled=true;try{await shareJobs.get(cid)?.catch(()=>{});const result=await api('collaborators?complex='+encodeURIComponent(cid));if(version===shareVersion){renderMembers(result.members);$('#share-status').textContent='';}}catch(e){if(version===shareVersion)$('#share-status').textContent=e.message;}finally{if(version===shareVersion){shareWorking=false;$('#share-invite').disabled=false;}}}
