let suggestionTimer=null,suggestionVersion=0,composingQuery=false;
function closeSuggestions(){clearTimeout(suggestionTimer);suggestionVersion++;$('#search-results').hidden=true;$('#search-results').replaceChildren();$('#query').setAttribute('aria-expanded','false');}
async function searchSuggestions(){const q=$('#query').value.trim();if(q.length<2){closeSuggestions();return;}const version=++suggestionVersion,root=$('#search-results');root.hidden=false;$('#query').setAttribute('aria-expanded','true');
 const normalize=value=>value.toLowerCase().replace(/\s+/g,'');const saved=state.complexes.filter(c=>normalize(c.name+' '+c.address).includes(normalize(q))).slice(0,5);
 const renderItems=items=>{root.replaceChildren();
 for(const c of items){const row=make('button','result');row.type='button';row.setAttribute('role','option');row.append(make('strong','',c.name),make('small','',c.address));const known=state.complexes.find(x=>x.name===c.name&&x.address===c.address),knownCount=known?known.buildings.reduce((n,b)=>n+b.visits.length,0):0;if(knownCount)row.append(make('span','badge','기록 '+knownCount));row.onclick=async()=>{if(!canLeave())return;let existing=state.complexes.find(x=>x.name===c.name&&x.address===c.address);if(!existing){existing={...c,id:uid(),buildings:[]};if(!await change(s=>s.complexes.unshift(existing)))return;}closeSuggestions();$('#query').value=c.name;$('#query').blur();rememberRecent(existing.id);selectComplex(existing.id);};row.onkeydown=e=>{if(e.key==='Escape'){closeSuggestions();$('#query').focus();return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const rows=[...root.querySelectorAll('.result')],index=rows.indexOf(row),next=index+(e.key==='ArrowDown'?1:-1);if(next<0)$('#query').focus();else rows[Math.min(next,rows.length-1)]?.focus();}};root.append(row);}
 };
 if(saved.length)renderItems(saved);else{const sk=make('div','search-skeleton');sk.setAttribute('aria-label','단지를 찾는 중');sk.append(make('span','skeleton line-a'),make('span','skeleton line-b'));root.replaceChildren(sk);}
 try{if(demo){if(!saved.length)root.replaceChildren(make('p','list-empty-note','샘플에서는 예시 단지를 선택해 주세요.'));return;}const{items}=await api('search?q='+encodeURIComponent(q));if(version!==suggestionVersion||q!==$('#query').value.trim())return;const merged=[...saved];for(const item of items){if(!merged.some(c=>c.name===item.name&&c.address===item.address))merged.push(item);}if(!merged.length){root.replaceChildren(make('p','list-empty-note','맞는 단지가 없어요. 동네 이름과 단지명을 함께 넣어 보세요.'));return;}renderItems(merged.slice(0,8));
 }catch(e){if(version===suggestionVersion&&q===$('#query').value.trim()&&!saved.length)root.replaceChildren(make('p','search-error',e.message));}}

function scheduleSuggestions(){closeSuggestions();if(composingQuery||$('#query').value.trim().length<2)return;suggestionTimer=setTimeout(searchSuggestions,350);}
$('#query').oninput=scheduleSuggestions;
$('#query').oncompositionstart=()=>{composingQuery=true;closeSuggestions();};
$('#query').oncompositionend=()=>{composingQuery=false;scheduleSuggestions();};
$('#query').onfocus=()=>{if($('#query').value.trim().length>=2)scheduleSuggestions();};
$('#query').onkeydown=e=>{if(e.isComposing)return;if(e.key==='Escape')closeSuggestions();if(e.key==='ArrowDown'&&!$('#search-results').hidden){e.preventDefault();$('#search-results').querySelectorAll('.result')[0]?.focus();}};
